/* Recorded treatment facts: B1 typography and native shared editor geometry. */
.vhome-treatment,
.vhome-treatment-editor {
  --vpt-ink: var(--vhome-b1-ink, #294b55);
  --vpt-muted: var(--vhome-b1-muted, #5d7580);
  --vpt-line: var(--vhome-b1-line, #dbe7e8);
  --vpt-soft-line: #edf2f3;
  --vpt-accent: var(--primary, #00838d);
  color: var(--vpt-ink);
  font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
  font-variant-numeric: tabular-nums;
  line-height: 1.5;
}
.vhome-treatment [hidden],
.vhome-treatment-editor [hidden] { display: none !important; }
.vhome-treatment,
.vhome-treatment .vpt-content,
.vhome-treatment .vpt-legacy,
.vhome-treatment-editor .vpt-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-16px);
  min-width: 0;
}
.vhome-treatment > *,
.vhome-treatment .vpt-content > * { min-width: 0; flex-shrink: 0; margin-block: 0; }
.vhome-treatment .vpt-toolbar,
.vhome-treatment .vpt-heading,
.vhome-treatment .vpt-diagnosis-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-12px) var(--space-16px);
  min-width: 0;
}
.vhome-treatment .vpt-heading { margin-bottom: var(--space-16px); }
.vhome-treatment .vpt-toolbar-copy { display: grid; flex: 1; gap: var(--space-4px); min-width: 0; }
html.vilda-home-workspace .vhome-native-patient-card .vhome-treatment .vpt-toolbar-copy > h3 {
  margin: 0;
  color: var(--vpt-ink);
  font-size: 20px;
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -.2px;
  text-transform: none;
}
.vhome-treatment .vpt-heading-copy,
.vhome-treatment .vpt-diagnosis-row > div { flex: 1; min-width: 0; }
.vhome-treatment .vpt-heading h4,
.vhome-treatment .vpt-timeline h5 {
  margin: 0;
  color: var(--vpt-ink);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -.2px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.vhome-treatment .vpt-heading p { margin-top: var(--space-4px); }
.vhome-treatment .vpt-meta,
.vhome-treatment-editor .vpt-meta {
  margin: 0;
  color: var(--vpt-muted);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.5;
