#vhomeVisitDetail .vd-result-row small { color: var(--vd-muted); font-size: 13px; font-weight: 450; }
#vhomeVisitDetail .vd-result-row > div small { display: block; }
#vhomeVisitDetail .vd-result-row[data-tone=normal] { border-left-color: #16858a; background: #f0f8f6; }
#vhomeVisitDetail .vd-result-row[data-tone=warn] { border-left-color: #b57a27; background: #fff8ed; }
#vhomeVisitDetail .vd-result-row[data-tone=danger] { border-left-color: #b94a55; background: #fff4f4; }
#vhomeVisitDetail .vd-facts { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: var(--space-16px); margin: 0; }
#vhomeVisitDetail .vd-facts dt { margin: 0 0 3px; color: var(--vd-muted); font-size: 13px; }
#vhomeVisitDetail .vd-facts dd { margin: 0; font-size: 15px; font-weight: 550; }
#vhomeVisitDetail .vd-chart { min-width: 0; margin: var(--space-12px) 0; }
#vhomeVisitDetail .vd-chart svg { display: block; width: 100%; height: auto; }
#vhomeVisitDetail .vd-record-actions { display: flex; flex-wrap: wrap; gap: var(--space-0-5); }
#vhomeVisitDetail .vd-grid + .vd-card { margin-top: var(--space-18px); }
#vhomeVisitDetail .vd-footer { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--space-10px); margin-top: var(--space-20px); }
#vhomeVisitDetail button[data-vd-action=compare] { border-color: var(--vd-accent) !important; background: var(--vd-accent) !important; color: white !important; }
#vhomeVisitDetail button[data-vd-action=compare]:hover:not(:disabled) { background: #00676c !important; }
#vhomeVisitDetail button[data-vd-action=collapse] { margin-bottom: var(--space-14px); }
#vhomeVisitDetail .vd-meta { margin: var(--space-10px) 0 0; color: var(--vd-muted); font-size: 13px; }
#vhomeVisitDetail .vd-notice { margin: 0 0 var(--space-18px); padding: var(--space-12px) 15px; color: #406269; background: #f0f7f6; border: var(--border-hairline) solid #d8e7e5; border-radius: var(--radius-8); }
#vhomeVisitDetail .vd-notice p { margin: 3px 0 0; }
#vhomeVisitDetail .vd-empty { margin: var(--space-12px) 0; font-size: 14px; color: var(--vd-muted); }
#vhomeVisitDetail :is(.vd-record,.vvisit-documents li) + :is(.vd-record,li) { margin-top: var(--space-12px); padding-top: var(--space-12px); border-top: var(--border-hairline) solid var(--vd-line); }
#vhomeVisitDetail .vvisit-documents ul { list-style: none; padding: 0; margin: 0; }
#vhomeVisitDetail :is(.vd-record,.vvisit-documents li) p { margin: var(--space-4px) 0; white-space: pre-wrap; overflow-wrap: anywhere; }
#vhomeVisitDetail :is(.vd-record small,.vvisit-documents li span) { color: var(--vd-muted); font-size: 13px; }
#vhomeVisitDetail .vd-compare-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
#vhomeVisitDetail .vd-compare-table caption { margin-bottom: var(--space-10px); font-size: 17px; font-weight: 600; text-align: start; }
#vhomeVisitDetail .vd-compare-table :is(th,td) { padding: 13px var(--space-10px); border: 0; border-bottom: var(--border-hairline) solid var(--vd-line); background: #fff; text-align: start; vertical-align: top; }
#vhomeVisitDetail .vd-compare-table th { font-weight: 550; }
#vhomeVisitDetail .vd-compare-table thead th { color: var(--vd-muted); font-size: 14px; }
#vhomeVisitDetail .vd-compare-table small { display: block; margin-top: 3px; color: var(--vd-muted); font-size: 13px; font-weight: 450; }
@media (max-width: 700px) {
  #vhomeVisitDetail .vd-grid { grid-template-columns: minmax(0,1fr); }
  #vhomeVisitDetail .vd-tabs { top: -14px; }
  #vhomeVisitDetail .vhome-dialog-body { padding: var(--space-14px); scrollbar-gutter: auto; }
}
@media (max-width: 480px) {
  #vhomeVisitDetail .vhome-dialog-body { padding: var(--space-12px); }
  #vhomeVisitDetail .vd-tabs { top: -12px; }
  #vhomeVisitDetail .vd-navigation { grid-template-columns: 44px auto 44px; gap: 2px; }
  #vhomeVisitDetail .vd-topbar { gap: var(--space-8px); }
  #vhomeVisitDetail .vd-navigation button { padding: var(--space-6px); }
  #vhomeVisitDetail :is(.vd-tabs,.vd-summary-tabs) button { padding: var(--space-6px) 3px; font-size: 13px; }
  #vhomeVisitDetail :is(.vd-card,.vvisit-documents) { padding: 13px; }
  #vhomeVisitDetail .vd-compare-table :is(th,td) { padding: 9px 3px; font-size: 14px; }
  #vhomeVisitDetail .vd-footer button { width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  #vhomeVisitDetail[open], #vhomeVisitDetail[open]::backdrop { animation: none; }
}

/* Read-only presentation of the revision returned by getPatientVisits.
 * Only the explicitly labeled comparison reads the open patient's form. */
(function (w) {
  'use strict';

  const missing = '—';
  const decimal = new Intl.NumberFormat('pl-PL', {maximumFractionDigits: 2});
  const savedDate = new Intl.DateTimeFormat('pl-PL', {
    timeZone: 'Europe/Warsaw', day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });
  const sources = {OLAF: 'OLAF / OLA', PALCZEWSKA: 'Palczewska', WHO: 'WHO', DS: 'Zemel 2015'};

  function number(value) {
    if (typeof value !== 'number' && typeof value !== 'string') return null;
    const input = String(value).trim().replace(',', '.');
    if (!input) return null;
    const parsed = Number(input);
    return Number.isFinite(parsed) ? parsed : null;
  }
  function positive(value) { const n = number(value); return n > 0 ? n : null; }

  function dayISO(value) {
    if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return '';
    const [year, month, day] = value.split('-').map(Number);
    const parsed = new Date(value + 'T12:00:00Z');
    return parsed.getUTCFullYear() === year && parsed.getUTCMonth() + 1 === month && parsed.getUTCDate() === day ? value : '';
  }
  function dayLabel(iso) { return iso ? iso.split('-').reverse().join('.') : 'Nie podano daty'; }

  function ageAtVisit(user, clinicalDay) {
    const years = number(user.age), extra = number(user.ageMonths), weeks = number(user.ageWeeks);
    let months = Number.isInteger(years) && years >= 0 && (extra === null || Number.isInteger(extra) && extra >= 0 && extra < 12)
      ? years * 12 + (extra || 0) : null;
    if (years === null && Number.isInteger(extra) && extra > 0 && extra < 12) months = extra;
    const dob = w.VildaDobAge, birth = dayISO(user.dobISO);
    const measured = dayISO(user.measuredAtISO) || clinicalDay;
    const calendar = birth && measured && dob?.ageFromDobISO?.(birth, new Date(measured + 'T12:00:00'));
    if (months === null && calendar) months = calendar.totalMonths;
    const recordedWeeks = Number.isInteger(weeks) && weeks >= 0 && weeks <= dob?.WEEKS_MAX ? weeks : null;
    if (months === null && recordedWeeks !== null) months = dob.monthsFromWeeks(recordedWeeks);
    if (months === null) return {months: null, exact: null, label: 'Nie podano wieku'};
    const consistent = calendar && calendar.totalMonths === months;
    const exact = consistent ? dob.exactMonthsFromDays(calendar.days) : null;
    const infantWeeks = consistent ? calendar.weeks : recordedWeeks;
    const label = dob?.weeksApplicable?.(months) && infantWeeks !== null
      ? dob.describeWeeks(infantWeeks) : dob?.describeAge?.({years: Math.floor(months / 12), ageMonths: months % 12}) || months + ' mies.';
    return {months, exact, label};
  }

  function metric(key, label, value, unit) {
    const display = value === null ? missing : key === 'bmi' && w.VildaBmi?.fmtBmi ? w.VildaBmi.fmtBmi(value) : decimal.format(value);
    const assessment = value === null ? 'Brak pomiaru' : key === 'bmi' ? 'Obliczono z masy i wzrostu' : 'Pomiar zapisany podczas wizyty';
    return {key, label, value, display, unit, assessment, tone: 'neutral'};
  }
  function measurements(user) {
    const height = positive(user.height), weight = positive(user.weight);
    const bmi = height !== null && weight !== null && typeof w.BMI === 'function' ? positive(w.BMI(weight, height)) : null;
    return [metric('height', 'Wysokość ciała', height, 'cm'), metric('weight', 'Masa ciała', weight, 'kg'), metric('bmi', 'BMI', bmi, 'kg/m²')];
  }
  function withUnit(item) { return item.value === null ? missing : item.display + ' ' + item.unit; }

  function reference(payload) {
    if (payload.clinical?.downSyndrome === true) return 'DS';
    const source = String(payload.zscore?.dataSource || '').trim().toUpperCase();
