      }
      const measuredWidth = Math.floor(container.getBoundingClientRect().width);
      const width = Math.max(275, Math.min(expanded ? 1050 : 560, measuredWidth || (expanded ? 780 : 360)));
      const height = Math.round(width * (expanded ? 0.56 : 0.64));
